def compute(vars):
    operating_income_values = [vars["v1"], vars["v2"], vars["v3"]]
    count = len(operating_income_values)
    average_operating_income = sum(operating_income_values) / count
    return {
        "value": average_operating_income,
        "trace": {
            "operating_income_values": operating_income_values,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
